// Parse session row and calculate verification_fresh
const rows = $input.all();
const row = rows.length && rows[0].json && rows[0].json['Session ID'] ? rows[0].json : null;
const input = $('When Executed by Another Workflow').first().json;
const settings = input.settings || {};
const reverifyWindowMin = Number(settings.REVERIFY_WINDOW_MIN || 15);

if (!row) {
  return [{ json: { found: false, expired: false, corrupt: false, state: {}, stage: 'IDLE', verified_at: null, verification_fresh: false } }];
}

let state = {};
let corrupt = false;
try {
  state = row.State ? JSON.parse(row.State) : {};
} catch (e) {
  state = {};
  corrupt = true;
}

const expiresAt = row['Expires At'] ? new Date(row['Expires At']) : null;
const now = new Date();
const expired = !!(expiresAt && !isNaN(expiresAt.getTime()) && expiresAt.getTime() < now.getTime());

const verifiedAtStr = row['Verified At'] || null;
let verificationFresh = false;
if (verifiedAtStr) {
  const vDate = new Date(verifiedAtStr);
  if (!isNaN(vDate.getTime())) {
    const ageMin = (now.getTime() - vDate.getTime()) / (1000 * 60);
    if (ageMin <= reverifyWindowMin) {
      verificationFresh = true;
    }
  }
}

return [{
  json: {
    found: true,
    expired,
    corrupt,
    state: expired ? {} : state,
    stage: expired ? 'IDLE' : (row.Stage || 'IDLE'),
    employee_code: row['Employee Code'] || '',
    verified_at: expired ? null : verifiedAtStr,
    verification_fresh: expired ? false : verificationFresh
  }
}];

const input = $input.first().json;
const timeoutMin = Number(input.session_timeout_min) > 0 ? Number(input.session_timeout_min) : 30;
const now = new Date();
const expiresAt = new Date(now.getTime() + timeoutMin * 60 * 1000);

let stateStr;
try {
  stateStr = JSON.stringify(input.state || {});
} catch (e) {
  stateStr = '{}';
}

return [{
  json: {
    'Session ID': input.session_id,
    'Employee Code': (input.state && input.state.employee && input.state.employee.code) || input.employee_code || '',
    State: stateStr,
    Stage: input.stage || 'IDLE',
    'Verified At': input.verified_at !== undefined ? input.verified_at : (input.state && input.state.verified_at ? input.state.verified_at : ''),
    'Updated At': now.toISOString(),
    'Expires At': expiresAt.toISOString()
  }
}];

const input = $input.first().json;
input.state = {};
input.stage = 'IDLE';
input.verified_at = '';
return [{ json: input }];

const out = $input.first().json;
return [{
  json: {
    ok: true,
    state: JSON.parse(out.State || '{}'),
    stage: out.Stage,
    verified_at: out['Verified At'],
    expires_at: out['Expires At']
  }
}];
